// Auto-rotate state management
let autoRotateEnabled = CONFIG.auto_rotate_speed !== 0;
let autoRotateActive = false;
let inactivityTimer = null;
const INACTIVITY_COOLDOWN = 5000; // 5 seconds

function stopAutoRotate() {
  autoRotateActive = false;
  if (inactivityTimer) clearTimeout(inactivityTimer);
}

function scheduleAutoRotateResume() {
  if (!autoRotateEnabled) return;
  if (inactivityTimer) clearTimeout(inactivityTimer);
  inactivityTimer = setTimeout(() => {
    autoRotateActive = true;
  }, INACTIVITY_COOLDOWN);
}

function toggleAutoRotate() {
  autoRotateEnabled = !autoRotateEnabled;
  if (autoRotateEnabled) {
    autoRotateActive = true;
    document.getElementById('btnAutoRotate').style.opacity = '1.0';
    document.getElementById('btnAutoRotate').title = 'Disable Auto-Rotate';
  } else {
    autoRotateActive = false;
    if (inactivityTimer) clearTimeout(inactivityTimer);
    document.getElementById('btnAutoRotate').title = 'Enable Auto-Rotate';
    document.getElementById('btnAutoRotate').style.opacity = '0.5';
  }
}

document.getElementById('btnExplore').addEventListener('click', () => tourSidebar.classList.remove('hidden'));
document.getElementById('btnCloseSidebar').addEventListener('click', () => tourSidebar.classList.add('hidden'));
document.getElementById('btnAutoRotate').addEventListener('click', toggleAutoRotate);

document.getElementById('btnFullscreen').addEventListener('click', () => {
  if (!document.fullscreenElement) document.documentElement.requestFullscreen();
  else if (document.exitFullscreen) document.exitFullscreen();
});

document.getElementById('btnHideUI').addEventListener('click', (e) => {
  const isHidden = appShell.classList.toggle('ui-hidden');
  e.currentTarget.title = isHidden ? 'Show UI' : 'Hide UI';
  document.getElementById('iconEye').style.display = isHidden ? 'none' : 'block';
  document.getElementById('iconEyeSlash').style.display = isHidden ? 'block' : 'none';
});

let renderer, camera, scene, sphereMesh, hotspotsLayer;
let currentPanoramaId = CONFIG.start_panorama_id;
let lon = 0, lat = 0, targetLon = 0, targetLat = 0;
let velocityLon = 0, velocityLat = 0;
let lastFrameTime = performance.now();
let pointerDown = false;
let pointerStart = { x: 0, y: 0, lon: 0, lat: 0 };
let lastPointer = { x: 0, y: 0 };
let isTransitioning = false;
let isDragging = false; 

const raycaster = new THREE.Raycaster();
const mouse = new THREE.Vector2();
let hotspotMeshes = [];
let currentHeadingOffset = 0;
let currentInvertRotation = false;

// Defer setup() to the next animation frame so the browser has performed
// a layout pass and viewerEl.clientWidth / clientHeight are non-zero.
// (They are 0 while appShell has display:none, causing a 0×0 renderer → black screen.)
requestAnimationFrame(() => { setup(); });

function setup() {
  renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
  renderer.setPixelRatio(window.devicePixelRatio || 1);
  const W = viewerEl.clientWidth || window.innerWidth;
  const H = viewerEl.clientHeight || window.innerHeight;
  renderer.setSize(W, H);
  viewerEl.appendChild(renderer.domElement);

  const initialFov = window.innerWidth < 768 ? 110 : 90;
  scene = new THREE.Scene();
  camera = new THREE.PerspectiveCamera(initialFov, W / H, 1, 1100);

  const geometry = new THREE.SphereGeometry(500, 72, 48);
  geometry.scale(-1, 1, 1);
  sphereMesh = new THREE.Mesh(geometry, new THREE.MeshBasicMaterial({ color: 0x111111 }));
  scene.add(sphereMesh);

  hotspotsLayer = document.createElement('div');
  hotspotsLayer.style.position = 'absolute';
  hotspotsLayer.style.inset = '0';
  hotspotsLayer.style.pointerEvents = 'none';
  viewerEl.appendChild(hotspotsLayer);

  renderer.domElement.addEventListener('pointerdown', onPointerDown);
  window.addEventListener('pointermove', onPointerMove);
  window.addEventListener('pointerup', onPointerUp);
  window.addEventListener('pointercancel', onPointerUp);
  renderer.domElement.addEventListener('wheel', onWheel, { passive: false });
  window.addEventListener('resize', onResize);

  renderer.domElement.addEventListener('click', (event) => {
    if (isTransitioning || isDragging) return;
    
    const rect = renderer.domElement.getBoundingClientRect();
    mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
    mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
    
    raycaster.setFromCamera(mouse, camera);
    const intersects = raycaster.intersectObjects(hotspotMeshes);
    
    if (intersects.length > 0) {
      const hotspotData = intersects[0].object.userData.hotspotData;
      if (hotspotData && hotspotData.destination_panorama_id) triggerTransition(hotspotData);
    }
  });

  renderPanoramaList();
  loadPanorama(currentPanoramaId);
  animate();
}

function renderPanoramaList() {
  panoramaListEl.innerHTML = '';
  
  const currentPano = CONFIG.panoramas.find(p => p.id === currentPanoramaId);
  const currentFloor = currentPano ? currentPano.floor : null;
  
  const mobileContainer = document.getElementById('mobileMinimapContainer');
  if (mobileContainer) {
      if (currentFloor && CONFIG.minimap_images && CONFIG.minimap_images[currentFloor]) {
          mobileContainer.classList.add('visible');
          document.getElementById('mobileMinimapImage').src = CONFIG.minimap_images[currentFloor];
          document.getElementById('mobileMinimapImage').style.display = 'block';
          const mobileOverlay = document.getElementById('mobileMinimapOverlay');
          const mobileFovCone = document.getElementById('mobileFovCone');
          mobileOverlay.innerHTML = '';
          mobileFovCone.style.display = 'none';
          
          if (CONFIG.minimap_hotspots) {
              const floorMhs = CONFIG.minimap_hotspots.filter(h => h.floor_type === currentFloor);
              floorMhs.forEach(mh => {
                  const dot = document.createElement('div');
                  dot.className = 'minimap-hotspot' + (mh.target_panorama_id === currentPanoramaId ? ' active' : '');
                  dot.style.left = `${mh.x * 100}%`;
                  dot.style.top = `${mh.y * 100}%`;
                  if (mh.target_panorama_id === currentPanoramaId) {
                      mobileFovCone.style.display = 'block';
                      mobileFovCone.style.left = `${mh.x * 100}%`;
                      mobileFovCone.style.top = `${mh.y * 100}%`;
                  }
                  dot.addEventListener('click', (e) => {
                      e.stopPropagation();
                      currentPanoramaId = mh.target_panorama_id;
                      renderPanoramaList();
                      loadPanorama(currentPanoramaId);
                  });
                  mobileOverlay.appendChild(dot);
              });
          }
      } else {
          mobileContainer.classList.remove('visible');
      }
  }

  const floorGroups = {};
  floorGroups['not_assigned'] = { name: 'Other Locations', items: [] };
  
  const floorLabels = CONFIG.floor_labels || {};
  CONFIG.panoramas.forEach(p => {
      const ftype = p.floor || 'not_assigned';
      if (!floorGroups[ftype]) {
          floorGroups[ftype] = { name: floorLabels[ftype] || ftype, items: [] };
      }
      floorGroups[ftype].items.push(p);
  });
  
  Object.keys(floorGroups).forEach(ftype => {
      const group = floorGroups[ftype];
      if (group.items.length === 0) return;
      
      const accordionItem = document.createElement('div');
      accordionItem.className = 'accordion-item';
      
      const header = document.createElement('div');
      header.className = 'floor-heading';
      header.innerHTML = `<span>${group.name}</span><span class="chevron ${currentFloor === ftype || (ftype === 'not_assigned' && !currentFloor) ? 'open' : ''}">▼</span>`;
      
      const content = document.createElement('div');
      content.className = `floor-content ${currentFloor === ftype || (ftype === 'not_assigned' && !currentFloor) ? 'expanded' : ''}`;
      
      header.addEventListener('click', () => {
          content.classList.toggle('expanded');
          header.querySelector('.chevron').classList.toggle('open');
      });
      
      if (CONFIG.minimap_images && CONFIG.minimap_images[ftype]) {
          const minimapContainer = document.createElement('div');
          minimapContainer.className = 'minimap-container';
          
          const minimapImage = document.createElement('img');
          minimapImage.className = 'minimap-image';
          minimapImage.src = CONFIG.minimap_images[ftype];
          minimapImage.alt = 'Minimap';
          minimapContainer.appendChild(minimapImage);

          const minimapOverlay = document.createElement('div');
          minimapOverlay.className = 'minimap-overlay';
          minimapContainer.appendChild(minimapOverlay);

          let fovCone = null;
          if (currentFloor === ftype) {
              fovCone = document.createElement('div');
              fovCone.id = 'fovCone'; 
              fovCone.className = 'fov-cone';
              fovCone.style.display = 'none';
              minimapContainer.appendChild(fovCone);
          }

          if (CONFIG.minimap_hotspots) {
              const floorMhs = CONFIG.minimap_hotspots.filter(h => h.floor_type === ftype);
              floorMhs.forEach(mh => {
                  const dot = document.createElement('div');
                  dot.className = 'minimap-hotspot';
                  if (currentFloor === ftype && mh.target_panorama_id === currentPanoramaId) {
                      dot.classList.add('active');
                      currentHeadingOffset = mh.heading_offset || 0;
                      currentInvertRotation = mh.invert_rotation || false;
                      if (fovCone) {
                          fovCone.style.display = 'block';
                          fovCone.style.left = `${mh.x * 100}%`;
                          fovCone.style.top = `${mh.y * 100}%`;
                      }
                  }
                  dot.style.left = `${mh.x * 100}%`;
                  dot.style.top = `${mh.y * 100}%`;
                  dot.title = CONFIG.panoramas.find(p => p.id === mh.target_panorama_id)?.name || '';
                  dot.addEventListener('click', (e) => {
                      e.stopPropagation();
                      currentPanoramaId = mh.target_panorama_id;
                      renderPanoramaList();
                      loadPanorama(currentPanoramaId);
                  });
                  minimapOverlay.appendChild(dot);
              });
          }
          content.appendChild(minimapContainer);
      }
      
      group.items.forEach(panorama => {
          content.appendChild(createPanoramaItem(panorama));
      });
      
      accordionItem.appendChild(header);
      accordionItem.appendChild(content);
      panoramaListEl.appendChild(accordionItem);
  });
}

function createPanoramaItem(panorama) {
  const item = document.createElement('button');
  item.className = 'panorama-item';
  if (panorama.id === currentPanoramaId) item.classList.add('active');
  item.innerHTML = `<strong>${panorama.name}</strong><span>Tap to view</span>`;
  item.addEventListener('click', () => {
    tourSidebar.classList.add('hidden');
    currentPanoramaId = panorama.id;
    renderPanoramaList();
    loadPanorama(currentPanoramaId);
  });
  return item;
}

function loadPanorama(panoramaId) {
  const panorama = CONFIG.panoramas.find(item => item.id === panoramaId);
  if (!panorama) return;
  panoramaTitleEl.textContent = panorama.name;

  loadingOverlay.classList.add('visible');
  const loader = new THREE.TextureLoader();
  loader.setCrossOrigin('');
  loader.load(
    panorama.file,
    texture => {
      texture.colorSpace = THREE.SRGBColorSpace;
      sphereMesh.material.color.setHex(0xffffff);
      if (sphereMesh.material.map) {
          sphereMesh.material.map.dispose();
      }
      sphereMesh.material.map = texture;
      sphereMesh.material.needsUpdate = true;
      renderHotspots();
      loadingOverlay.classList.remove('visible');

      // Activate auto-rotate after first panorama loads
      if (autoRotateEnabled && CONFIG.auto_rotate_speed) {
        autoRotateActive = true;
      }

      if (isTransitioning) {
        // Keep the view direction the user was already looking at —
        // view angle carries straight through to the new room.
        targetLon = lon;
        targetLat = lat;
        const overlay = document.getElementById('fadeOverlay');
        requestAnimationFrame(() => {
          overlay.classList.remove('visible');
        });
        isTransitioning = false;
        document.querySelectorAll('.hotspot').forEach(el => el.classList.remove('hidden'));
      } else {
        if (panorama.initialYaw !== undefined) {
          lon = targetLon = panorama.initialYaw;
          lat = targetLat = (panorama.initialPitch !== undefined) ? panorama.initialPitch : 0;
        }
      }
    },
    undefined,
    () => {
      loadingOverlay.textContent = 'Failed to load panorama';
      loadingOverlay.classList.add('visible');
    }
  );
}

function triggerTransition(hotspot) {
  if (isTransitioning) return;
  isTransitioning = true;

  // No camera pan — view direction carries straight through to the new room.
  // Show the overlay immediately, then load new panorama after 200ms.
  document.querySelectorAll('.hotspot').forEach(el => el.classList.add('hidden'));

  const overlay = document.getElementById('fadeOverlay');
  overlay.classList.add('visible');
  setTimeout(() => {
    currentPanoramaId = hotspot.destination_panorama_id;
    renderPanoramaList();
    loadPanorama(currentPanoramaId);
  }, 200);
}

function createGroundArrowTexture(color) {
    const canvas = document.createElement('canvas');
    canvas.width = 256; canvas.height = 256;
    const ctx = canvas.getContext('2d');
    ctx.shadowColor = 'rgba(0,0,0,0.6)'; ctx.shadowBlur = 12; ctx.shadowOffsetX = 0; ctx.shadowOffsetY = 8;
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(128, 40); ctx.lineTo(216, 140); ctx.lineTo(160, 140); ctx.lineTo(128, 100); ctx.lineTo(96, 140); ctx.lineTo(40, 140);
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = color; ctx.lineWidth = 14;
    ctx.beginPath(); ctx.arc(128, 128, 100, 0, Math.PI * 2); ctx.stroke();
    return new THREE.CanvasTexture(canvas);
}

function renderHotspots() {
  hotspotsLayer.innerHTML = '';
  hotspotMeshes.forEach(mesh => scene.remove(mesh));
  hotspotMeshes = [];

  const hotspots = CONFIG.hotspots.filter(item => item.panorama_id === currentPanoramaId);
  for (const hotspot of hotspots) {
    if (hotspot.type === 'area_outline' || hotspot.type === 'polygon_highlight' || hotspot.type === 'ground_arrow') {
       let mesh;

       if (hotspot.type === 'ground_arrow') {
           const texture = createGroundArrowTexture(hotspot.color);
           const size = (hotspot.size || 50) * 2;
           const geometry = new THREE.PlaneGeometry(size, size);
           const material = new THREE.MeshBasicMaterial({
               map: texture, transparent: true, depthWrite: false, side: THREE.DoubleSide
           });
           mesh = new THREE.Mesh(geometry, material);
           const pos = vectorFromYawPitch(hotspot.yaw, hotspot.pitch, 300);
           mesh.position.copy(pos);
           mesh.rotation.x = -Math.PI / 2;
           let yawAngle = hotspot.target_yaw !== undefined && hotspot.target_yaw !== null ? hotspot.target_yaw : hotspot.yaw;
           mesh.rotation.z = -THREE.MathUtils.degToRad(yawAngle);
       } else {
           const w = hotspot.width || 100;
           const h = hotspot.height || 100;
           let c = hotspot.polygon_corners;
           if (!c || c.length !== 4) {
               c = [{x: -w/2, y: h/2}, {x: w/2, y: h/2}, {x: w/2, y: -h/2}, {x: -w/2, y: -h/2}];
           }

           const geometry = new THREE.BufferGeometry();
           const vertices = new Float32Array([
               c[0].x, c[0].y, 0,
               c[1].x, c[1].y, 0,
               c[2].x, c[2].y, 0,
               c[3].x, c[3].y, 0
           ]);
           geometry.setAttribute('position', new THREE.BufferAttribute(vertices, 3));
           geometry.setIndex([0, 3, 1, 1, 3, 2]);

           const material = new THREE.MeshBasicMaterial({
               color: hotspot.color,
               transparent: true,
               opacity: hotspot.type === 'area_outline' ? 0.0 : 0.4,
               side: THREE.DoubleSide,
               depthWrite: false,
               depthTest: false
           });

           mesh = new THREE.Mesh(geometry, material);

           if (hotspot.type === 'area_outline') {
               const edges = new THREE.EdgesGeometry(geometry);
               const line = new THREE.LineSegments(edges, new THREE.LineBasicMaterial({ color: hotspot.color, linewidth: 2, depthTest: false }));
               mesh.add(line);
           }

           const pos = vectorFromYawPitch(hotspot.yaw, hotspot.pitch, 480);
           mesh.position.copy(pos);
           mesh.lookAt(0, 0, 0); 
       }

       mesh.userData = { hotspotData: hotspot };
       scene.add(mesh);
       hotspotMeshes.push(mesh);

       const labelEl = document.createElement('div');
       labelEl.className = 'hotspot-label-top';
       labelEl.textContent = hotspot.name;
       labelEl.style.position = 'absolute';
       labelEl.style.pointerEvents = 'none';
       labelEl.style.bottom = 'auto'; 
       labelEl.style.background = 'transparent';
       labelEl.style.boxShadow = 'none';
       labelEl.style.color = '#ffffff';
       labelEl.style.textShadow = '0 2px 8px rgba(0,0,0,0.9), 0 0 4px rgba(0,0,0,0.5)';
       labelEl.dataset.hotspotId = hotspot.id;
       hotspotsLayer.appendChild(labelEl);
    } else {
       const el = document.createElement('div');
       el.className = `hotspot type-${hotspot.type || 'icon'} ${hotspot.animated ? 'pulse' : ''}`;
       el.dataset.hotspotId = hotspot.id;

       el.style.width = `${hotspot.size}px`;
       el.style.height = `${hotspot.size}px`;
       el.style.background = hotspot.color;
       const glyph = document.createElement('span');
       glyph.className = 'glyph';
       if (hotspot.icon === 'custom' && hotspot.custom_icon) {
         el.style.backgroundImage = `url(${hotspot.custom_icon})`;
         el.style.backgroundSize = 'cover';
         el.style.backgroundPosition = 'center';
       } else {
         glyph.textContent = iconGlyph(hotspot.icon);
       }
       el.appendChild(glyph);
       const label = document.createElement('div');
       label.className = 'hotspot-label'; label.textContent = hotspot.name;
       el.appendChild(label);

       el.addEventListener('click', event => {
         event.stopPropagation();
         if (hotspot.destination_panorama_id) triggerTransition(hotspot);
       });
       hotspotsLayer.appendChild(el);
    }
  }
}

function animate() {
  const now = performance.now();
  const dt = Math.min((now - lastFrameTime) / 1000, 0.1);
  lastFrameTime = now;
  requestAnimationFrame(animate);
  if (!pointerDown && autoRotateActive && autoRotateEnabled && CONFIG.auto_rotate_speed) {
      targetLon += CONFIG.auto_rotate_speed;
  }
  // Frame-rate independent damping
  const dampingFactor = 1 - Math.pow(0.001, dt);
  if (!pointerDown) {
      targetLon += velocityLon * dt * 60;
      targetLat += velocityLat * dt * 60;
      velocityLon *= Math.pow(0.92, dt * 60);
      velocityLat *= Math.pow(0.92, dt * 60);
      if (Math.abs(velocityLon) < 0.01) velocityLon = 0;
      if (Math.abs(velocityLat) < 0.01) velocityLat = 0;
  }
  lon += (targetLon - lon) * dampingFactor;
  lat += (targetLat - lat) * dampingFactor;
  updateCamera();
  projectHotspots();
  
  const fovCone = document.getElementById('fovCone');
  if (fovCone && fovCone.style.display !== 'none') {
      const currentLon = currentInvertRotation ? -lon : lon;
      fovCone.style.transform = `translate(-50%, -100%) rotate(${currentLon + currentHeadingOffset}deg)`;
  }
  const mobileFovCone = document.getElementById('mobileFovCone');
  if (mobileFovCone && mobileFovCone.style.display !== 'none') {
      const currentLon = currentInvertRotation ? -lon : lon;
      mobileFovCone.style.transform = `translate(-50%, -100%) rotate(${currentLon + currentHeadingOffset}deg)`;
  }
  
  renderer.render(scene, camera);
}

function projectHotspots() {
  const cameraDir = new THREE.Vector3();
  camera.getWorldDirection(cameraDir);
  const W = viewerEl.clientWidth, H = viewerEl.clientHeight;
  const hotspots = CONFIG.hotspots.filter(item => item.panorama_id === currentPanoramaId);
  for (const hotspot of hotspots) {
    const el = hotspotsLayer.querySelector(`[data-hotspot-id="${hotspot.id}"]`);
    if (!el) continue;

    const hotspotDir = vectorFromYawPitch(hotspot.yaw, hotspot.pitch, 1).normalize();
    const isFront = cameraDir.dot(hotspotDir) > 0;

    if (!isFront) { el.classList.add('hidden'); continue; }
    const vector = vectorFromYawPitch(hotspot.yaw, hotspot.pitch, 460).project(camera);
    const x = (vector.x * 0.5 + 0.5) * W;
    const y = (-vector.y * 0.5 + 0.5) * H;
    el.style.left = `${x}px`;
    el.style.top = `${y}px`;
    el.classList.remove('hidden');
    if (hotspot.type === 'ground_arrow') {
        el.style.transform = 'translate(-50%, 20px)';
    } else {
        el.style.transform = `translate(-50%, -50%) ${hotspot.animated ? 'scale(1)' : ''}`;
    }
  }
}

function updateCamera() {
  lat = Math.max(-85, Math.min(85, lat));
  targetLat = Math.max(-85, Math.min(85, targetLat));
  camera.lookAt(vectorFromYawPitch(lon, lat, 500));
}

function onPointerDown(event) {
  if (isTransitioning) return;
  pointerDown = true;
  isDragging = false;
  pointerStart = { x: event.clientX, y: event.clientY, lon: targetLon, lat: targetLat };
  lastPointer = { x: event.clientX, y: event.clientY };
  velocityLon = 0; velocityLat = 0;
  stopAutoRotate();
  scheduleAutoRotateResume();
}

function onPointerMove(event) {
  if (isTransitioning || !pointerDown) return;
  if (Math.abs(event.clientX - pointerStart.x) > 5 || Math.abs(event.clientY - pointerStart.y) > 5) {
      isDragging = true;
  }
  
  const deltaX = event.clientX - lastPointer.x;
  const deltaY = event.clientY - lastPointer.y;
  lastPointer.x = event.clientX;
  lastPointer.y = event.clientY;

  const newTargetLon = targetLon + deltaX * 0.12;
  let newTargetLat = targetLat + deltaY * 0.12;

  if (newTargetLat > 85) newTargetLat = 85;
  if (newTargetLat < -85) newTargetLat = -85;

  velocityLon = (newTargetLon - targetLon) * 0.5;
  velocityLat = (newTargetLat - targetLat) * 0.5;
  targetLon = newTargetLon;
  targetLat = newTargetLat;
}

function onPointerUp() {
  pointerDown = false;
}

function onWheel(event) {
  if (isTransitioning) return;
  event.preventDefault();
  const maxFov = window.innerWidth < 768 ? 110 : 90;
  camera.fov = THREE.MathUtils.clamp(camera.fov + event.deltaY * 0.03, 30, maxFov);
  camera.updateProjectionMatrix();
  stopAutoRotate();
  scheduleAutoRotateResume();
}

function onResize() {
  const isMobile = window.innerWidth < 768;
  const maxFov = isMobile ? 110 : 90;
  if (camera.fov > maxFov || camera.fov === (isMobile ? 90 : 110)) {
    camera.fov = maxFov;
  }
  camera.aspect = viewerEl.clientWidth / viewerEl.clientHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(viewerEl.clientWidth, viewerEl.clientHeight);
}

function vectorFromYawPitch(yawDeg, pitchDeg, radius) {
  const yaw = THREE.MathUtils.degToRad(yawDeg);
  const pitch = THREE.MathUtils.degToRad(pitchDeg);
  return new THREE.Vector3(
    radius * Math.cos(pitch) * Math.sin(yaw),
    radius * Math.sin(pitch),
    radius * Math.cos(pitch) * Math.cos(yaw)
  );
}

function iconGlyph(icon) {
  switch (icon) {
    case 'arrow': return '→';
    case 'house': return '⌂';
    case 'door': return '⎋';
    case 'circle': return '•';
    default: return '●';
  }
}
